mapper.select:
select * from room


        and building = #{building}


        and room_type = #{roomType}


        and capacity >= #{minCapacity}


        and status = #{status}


order by building, floor_no, room_no

select r.*
from room r
where r.status = 1

    and r.capacity >= #{minCapacity}


    and r.room_type = #{roomType}

and not exists (
    select 1
    from class_time ct
    join course c on ct.course_id = c.id
    where ct.room_id = r.id
      and c.term = #{term}
      and ct.weekday = #{weekday}
      and ct.start_period <= #{endPeriod} and ct.end_period >= #{startPeriod}
      and ct.start_week <= #{endWeek} and ct.end_week >= #{startWeek}

        and ct.course_id != #{excludeCourseId}

)

order by r.capacity asc, r.building asc, r.floor_no asc, r.room_no asc
limit #{limit}
